create or replace function public.normalize_invoice(p text) returns text language sql immutable set search_path=public,pg_temp as $$ select upper(regexp_replace(coalesce(p,''),'[^A-Za-z0-9]','','g')) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin insert into public.user_profiles(id,organization_id,full_name,mobile,role,status) values(new.id,'91336824-c4f4-4ee0-b5ec-3525a1bc43e5',coalesce(nullif(new.raw_user_meta_data->>'full_name',''),'FuelPulse User'),public.normalize_mobile(coalesce(new.phone,'')),'USER','ACTIVE') on conflict(id) do update set full_name=coalesce(nullif(excluded.full_name,''),user_profiles.full_name),mobile=coalesce(nullif(excluded.mobile,''),user_profiles.mobile),updated_at=now(); return new; end; $$;
alter function public.handle_new_user() owner to postgres;
revoke all on function public.handle_new_user() from public,anon,authenticated;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create unique index if not exists receipt_redemptions_receipt_unique on public.receipt_redemptions(receipt_id);
create or replace function public.claim_offer_atomic(p_user_id uuid,p_offer_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare u public.user_profiles%rowtype;o public.offers%rowtype;v_balance bigint;c public.offer_claims%rowtype;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'forbidden';end if;if p_user_id is null or p_offer_id is null then raise exception 'invalid_request';end if;perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));select * into u from public.user_profiles where id=p_user_id and status='ACTIVE';if not found then raise exception 'account_inactive';end if;select * into o from public.offers where id=p_offer_id and organization_id=u.organization_id and active=true;if not found then raise exception 'offer_unavailable';end if;select * into c from public.offer_claims where offer_id=o.id and user_id=p_user_id limit 1;if found then raise exception 'already_claimed';end if;select coalesce(sum(points),0) into v_balance from public.points_ledger where user_id=p_user_id;if v_balance<o.points_cost then raise exception 'insufficient_points';end if;insert into public.offer_claims(offer_id,user_id,points_spent) values(o.id,p_user_id,o.points_cost) returning * into c;insert into public.points_ledger(user_id,points,reason) values(p_user_id,-o.points_cost,'Offer claimed: '||o.title);return jsonb_build_object('decision','CLAIMED','offer_id',o.id,'points_spent',o.points_cost,'claim_id',c.id);exception when unique_violation then raise exception 'already_claimed';end; $$;
alter function public.claim_offer_atomic(uuid,uuid) owner to postgres;
revoke all on function public.claim_offer_atomic(uuid,uuid) from public,anon,authenticated;
grant execute on function public.claim_offer_atomic(uuid,uuid) to service_role;
